import { getLocalData } from '../utils/storage';

function Profile() {
  const currentUser = getLocalData('currentUser');

  if (!currentUser) {
    return <p className="text-muted">Không tìm thấy thông tin người dùng.</p>;
  }

  const rows = [
    { label: 'Họ tên', value: currentUser.name || '--' },
    { label: 'Tên đăng nhập', value: currentUser.username || '--' },
    { label: 'Vai trò', value: currentUser.role === 'admin' ? 'Quản trị viên' : 'Nhân viên' },
    { label: 'Email', value: currentUser.email || 'Chưa cập nhật' },
    { label: 'Số điện thoại', value: currentUser.phone || 'Chưa cập nhật' },
    { label: 'Phòng ban', value: currentUser.department || 'Chưa cập nhật' },
  ];

  const firstLetter = (currentUser.name || currentUser.username || 'U').charAt(0).toUpperCase();

  return (
    <div>
      <h4 className="mb-1">Hồ sơ cá nhân</h4>
      <p className="text-muted mb-3" style={{ fontSize: '14px' }}>
        Thông tin tài khoản của bạn.
      </p>

      <div className="row g-3 align-items-start">
        {/* Avatar card */}
        <div className="col-md-3">
          <div className="card text-center">
            <div className="card-body">
              <div
                className="rounded-circle bg-primary text-white d-flex align-items-center justify-content-center fw-bold mx-auto mb-3"
                style={{ width: '72px', height: '72px', fontSize: '28px' }}
              >
                {firstLetter}
              </div>
              <p className="fw-semibold mb-1">{currentUser.name || currentUser.username}</p>
              <p className="text-muted mb-0" style={{ fontSize: '12px' }}>
                {currentUser.role === 'admin' ? 'Quản trị viên' : 'Nhân viên'}
              </p>
            </div>
          </div>
        </div>

        {/* Thông tin chi tiết */}
        <div className="col-md-9">
          <div className="card">
            <div className="card-header bg-white fw-semibold">Thông tin tài khoản</div>
            <div className="card-body p-0">
              <table className="table table-bordered mb-0">
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.label}>
                      <th className="table-light" style={{ width: '180px', fontSize: '14px' }}>
                        {row.label}
                      </th>
                      <td style={{ fontSize: '14px' }}>{row.value}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Profile;
